def calculate_total(items):
    total = 0
    for item in items:
        total += item.price * item.quantity
    return total

class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, product, quantity):
        self.items.append({'product': product, 'quantity': quantity})

    def get_total(self):
        return calculate_total(self.items)

